        "hairStyle": "short" | "long" | "bald",
        "outfitTop": "tshirt" | "hoodie",
        "outfitTopColor": "#hex",
        "outfitBottomColor": "#hex",
        "shoeColor": "#hex",
        "eyeColor": "#hex"
